reference_solution:
def add_to_array_number(num, k):
 answer=[];i=len(num)-1;carry=k
 while i>=0 or carry:
  if i>=0:carry+=num[i];i-=1
  answer.append(carry%10);carry//=10
 return (num[:i+1] if i>=0 else [])+answer[::-1]

